    for color in colors:
        cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == color}
        while cells:
            seed = next(iter(cells))
            stack = [seed]
            cells.remove(seed)
            comp = []
            while stack:
                r, c = stack.pop()
                comp.append((r, c))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (r + dr, c + dc)
                    if p in cells:
                        cells.remove(p)
                        stack.append(p)
            comps.append((color, comp))

    top = min(min(r for r, c in comp) for _, comp in comps)
    out = [[0] * w for _ in range(h)]
    for color, comp in comps:
        shift = top - min(r for r, c in comp)
        for r, c in comp:
